UPDATE report.template_parameters
SET displayorder = CASE name
    WHEN 'program_name' THEN 1
    WHEN 'supplying_facility' THEN 2
    WHEN 'category' THEN 3
    WHEN 'from_date' THEN 4
    WHEN 'to_date' THEN 5
END
WHERE templateid = '4cccd62b-6a43-484c-8121-cd9e255447e9'
  AND name IN ('program_name', 'supplying_facility', 'category', 'from_date', 'to_date');

